from pathlib import Path
import base64,json,hashlib,datetime,shutil,subprocess,sqlite3
v=json.loads(base64.b64decode(''));base=Path('/opt/kiwoom/current');engine=base/'auto_trading.py';page=Path('/opt/kiwoom/dashboard-source/dist/index.html');unit=Path('/etc/systemd/system/moa-real-performance.service')
