for id,key,hashkey in [('signal-validation-module','signalUi','signalHash'),('auto-trading-execution-module','autoUi','autoHash')]:
 tag='<script id="'+id+'">';a=s.index(tag)+len(tag);b=s.index('</script>',a);assert hashlib.sha256(s[a:b].strip().encode()).hexdigest()==v[hashkey],id+' changed';s=s[:a]+'\n'+v[key].strip()+'\n'+s[b:]
