dbpath='/opt/kiwoom/state/auto-trading.sqlite3';source=sqlite3.connect('file:'+dbpath+'?mode=ro',uri=True);backup=sqlite3.connect(dbpath+suffix);source.backup(backup);source.close();backup.close()
(base/'auto_performance_history.py').write_text(v['helper']);(base/'test_auto_performance_history.py').write_text(v['test'])
